// stores/user.js
import { createStore } from "vuex";
import axios from "axios";

const user = createStore({
  state: {
    user: null, // 存储用户信息
  },
  mutations: {
    setUser(state, user) {
      state.user = user; // 设置用户信息
      localStorage.setItem("user", JSON.stringify(user)); // 同时存储到 localStorage
    },
    clearUser(state) {
      state.user = null; // 清空用户信息
      localStorage.removeItem("user"); // 移除 localStorage 中的用户信息
    },
    initializeUser(state) {
      const userData = localStorage.getItem("user"); // 从 localStorage 中获取用户数据
      if (userData) {
        try {
          state.user = JSON.parse(userData); // 如果存在数据，则解析并设置
        } catch (error) {
          console.error("解析用户数据时出错:", error);
          state.user = null; // 解析失败情况下 reset
        }
      }
    },
  },
  actions: {
    async login({ commit }, credentials) {
      try {
        const response = await axios.post(
          "http://localhost:5000/api/auth/login",
          credentials,
        );
        const data = response.data.data; // 获取正确的数据格式
        // 提取用户信息和 token 数据
        if (data.user) {
          commit("setUser", data.user); // 存储用户信息
          return data; // 返回数据以便于在组件中使用
        }
      } catch (error) {
        console.error("登录请求失败", error);
        throw new Error("登录请求失败"); // 可以在组件中捕获并处理
      }
    },
  },
  getters: {
    user: (state) => {
      const userData = localStorage.getItem("user"); // 从 localStorage 中获取用户数据
      if (!userData) {
        // 如果 userData 为空则返回空对象
        return {};
      }
      try {
        return state.user || JSON.parse(userData); // 尝试解析数据
      } catch (error) {
        console.error("解析用户数据时出错", error);
        return {}; // 如果解析失败，也返回空对象
      }
    },
    userPhoneNumber(state) {
      return state.user ? state.user.phoneNumber : null; // 获取用户电话
    },
    userId(state) {
      return state.user ? state.user.id : null; // 获取用户ID
    },
    userBalance(state) {
      return state.user ? state.user.AccountBalance : null; // 获取用户余额
    },
    userNickname(state) {
      return state.user ? state.user.nickname : "用户"; // 获取用户昵称
    },
    userAvatar(state) {
      return state.user ? state.user.avatar : "/assets/avatar.png"; // 获取用户头像
    },
  },
});

export default user;
